import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { formatRelativeTime } from '../utils/helpers';

const Navbar = ({ toggleSidebar, sidebarOpen, isMobile }) => {
  const { user, logout } = useAuth();
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const navigate = useNavigate();

  // Sample notifications data
  const [notifications, setNotifications] = useState([
    {
      id: 1,
      title: 'New Event',
      message: 'City festival starts next week',
      type: 'event',
      createdAt: new Date(Date.now() - 3600000),
      read: false
    },
    // ... more notifications
  ]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const toggleNotifications = () => {
    setNotificationsOpen(!notificationsOpen);
    setUserMenuOpen(false);
  };

  const toggleUserMenu = () => {
    setUserMenuOpen(!userMenuOpen);
    setNotificationsOpen(false);
  };

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  return (
    <header className="app-navbar">
      <div className="navbar-container">
        {!isMobile && (
          <button 
            className="sidebar-toggle"
            onClick={toggleSidebar}
            aria-label={sidebarOpen ? 'Collapse sidebar' : 'Expand sidebar'}
          >
            <i className={`fas fa-${sidebarOpen ? 'times' : 'bars'}`} />
          </button>
        )}
        
        <Link className="navbar-brand" to="/dashboard">
          <i className="fas fa-city" />
          <span>Smart City</span>
        </Link>

        {isMobile && (
          <button 
            className="mobile-menu-toggle"
            onClick={toggleSidebar}
            aria-label={sidebarOpen ? 'Close menu' : 'Open menu'}
          >
            <i className={`fas fa-${sidebarOpen ? 'times' : 'bars'}`} />
          </button>
        )}

        <div className="navbar-actions">
          {user && (
            <>
              <div className="nav-item dropdown">
                <button 
                  className="nav-link notification-btn"
                  onClick={toggleNotifications}
                  aria-expanded={notificationsOpen}
                >
                  <i className="fas fa-bell" />
                  {unreadCount > 0 && (
                    <span className="notification-badge">{unreadCount}</span>
                  )}
                </button>
                
                <div className={`dropdown-menu notification-dropdown ${notificationsOpen ? 'show' : ''}`}>
                  <div className="dropdown-header">
                    <h3>Notifications</h3>
                    <button className="refresh-btn">
                      <i className="fas fa-sync-alt" />
                    </button>
                  </div>
                  
                  <div className="notification-list">
                    {notifications.length > 0 ? (
                      notifications.map(notification => (
                        <div
                          key={notification.id}
                          className={`notification-item ${!notification.read ? 'unread' : ''}`}
                        >
                          <div className="notification-icon">
                            <i className={`fas ${getNotificationIcon(notification.type)}`} />
                          </div>
                          <div className="notification-content">
                            <h4>{notification.title}</h4>
                            <p>{notification.message}</p>
                            <small>{formatRelativeTime(notification.createdAt)}</small>
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="empty-notifications">
                        <p>No notifications</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
              
              <div className="nav-item dropdown">
                <button 
                  className="nav-link user-menu-btn"
                  onClick={toggleUserMenu}
                  aria-expanded={userMenuOpen}
                >
                  <span className="user-name">{user.firstName}</span>
                  <div className="user-avatar">
                    {user.avatar ? (
                      <img 
                        src={user.avatar} 
                        alt={`${user.firstName} ${user.lastName}`}
                        loading="lazy"
                      />
                    ) : (
                      <div className="avatar-placeholder">
                        {user.firstName.charAt(0)}{user.lastName.charAt(0)}
                      </div>
                    )}
                  </div>
                </button>
                
                <div className={`dropdown-menu user-dropdown ${userMenuOpen ? 'show' : ''}`}>
                  <div className="user-profile">
                    <div className="user-avatar-large">
                      {user.avatar ? (
                        <img 
                          src={user.avatar} 
                          alt={`${user.firstName} ${user.lastName}`}
                          loading="lazy"
                        />
                      ) : (
                        <div className="avatar-placeholder">
                          {user.firstName.charAt(0)}{user.lastName.charAt(0)}
                        </div>
                      )}
                    </div>
                    <div className="user-info">
                      <h3>{user.firstName} {user.lastName}</h3>
                      <p>{user.email}</p>
                      <span className="user-role">{user.roles?.[0] || 'User'}</span>
                    </div>
                  </div>
                  
                  <div className="dropdown-divider" />
                  
                  <Link className="dropdown-item" to="/profile">
                    <i className="fas fa-user" /> Profile
                  </Link>
                  <Link className="dropdown-item" to="/settings">
                    <i className="fas fa-cog" /> Settings
                  </Link>
                  
                  <div className="dropdown-divider" />
                  
                  <button className="dropdown-item" onClick={handleLogout}>
                    <i className="fas fa-sign-out-alt" /> Logout
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </header>
  );
};

function getNotificationIcon(type) {
  switch (type) {
    case 'event': return 'fa-calendar-alt';
    case 'transportation': return 'fa-bus';
    case 'news': return 'fa-newspaper';
    case 'feedback': return 'fa-comment-alt';
    case 'incident': return 'fa-exclamation-triangle';
    case 'account': return 'fa-user-circle';
    case 'tour': return 'fa-map-marked-alt';
    default: return 'fa-bell';
  }
}

export default Navbar;
